$path = 'H:/Other/Degrees of Lewdity/Degrees of Lewdity 0.6.2.2.html'
$backup = 'H:/Other/Degrees of Lewdity/Degrees of Lewdity 0.6.2.2.pre-two-hand-player-complete-2026-08-23.html'
Copy-Item -LiteralPath $path -Destination $backup
$text = [IO.File]::ReadAllText($path)
$changes = @(
  @{ Name = 'actionsshaftrub'; Old = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')); New = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) },
  @{ Name = 'npc botharm render state'; Old = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('CQkJY2FzZSAib3RoZXJhbnVzIjoKCQkJCXJldHVybiB7fTsKCQkJY2FzZSAiY2xvdGhlZCI6IC8vIEh1aD8gQXNraW5nIFB1cmkgLSBGb3Igd2hlbiB5b3UgbmVlZCB0byB1bmRyZXNzIE5QQ3MgYmVmb3JlIHVzaW5nIHRoZSBwYXJ0LgoJCQkJcmV0dXJuIHt9OwoJCQljYXNlICJsZWZ0YXJtIjo=')); New = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) },
  @{ Name = 'combined work continuation'; Old = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')); New = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) },
  @{ Name = 'combined stop continuation'; Old = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('CQk8PGlmICRsZWZ0YWN0aW9uIGlzICJsZWZ0c3RvcHBlbmlzIiBhbmQgJE5QQ0xpc3RbJGxlZnR0YXJnZXRdLnBlbmlzIGlzICJsZWZ0YXJtIj4+')); New = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) }
)
foreach ($change in $changes) {
  $count = ([regex]::Matches($text, [regex]::Escape($change.Old))).Count
  if ($count -ne 1) { throw ('Replacement '+$change.Name+' expected 1 match, found '+$count) }
  $text = $text.Replace($change.Old, $change.New)
}
[IO.File]::WriteAllText($path, $text, [Text.UTF8Encoding]::new($false))